function refreshTransportIcons(){for(const [id,name]of Object.entries({play:audio.paused?'play':'pause',prev:'previous',next:'next',shuffle:'shuffle',repeat:'repeat',like:'heart',mute:'volume',expandPlayer:'expand'})){const node=$('#'+id);if(node)node.innerHTML=playerIcon(name)}}
const syncBeforeRedesign=sync;sync=function(){syncBeforeRedesign();refreshTransportIcons()};for(const name of ['play','pause','ended'])audio.addEventListener(name,refreshTransportIcons);refreshTransportIcons();
const navIcons={home:'play',search:'search',library:'library',favorites:'heart',appearance:'sliders'};document.querySelectorAll('.sidebar nav [data-page]').forEach(node=>{const span=node.querySelector('span'),name=span?.textContent||node.getAttribute('aria-label');node.innerHTML=playerIcon(navIcons[node.dataset.page]||'play')+'<span>'+esc(name)+'</span>';if(node.dataset.page==='search')node.insertAdjacentHTML('beforeend','<kbd>/</kbd>')});
const toggleLikeBeforeFeedback=toggleLike;toggleLike=function(id){if(!id)return;toggleLikeBeforeFeedback(id);const liked=likes.has(id);for(const b of document.querySelectorAll('[data-like]'))if(b.dataset.like===id){b.classList.toggle('is-on',liked);b.setAttribute('aria-pressed',String(liked));b.setAttribute('aria-label',liked?'Убрать из любимого':'В любимое');b.textContent=liked?'♥':'♡'}if(current?.id===id){for(const b of document.querySelectorAll('#like,[data-focus-control="like"]')){b.classList.toggle('is-on',liked);b.setAttribute('aria-pressed',String(liked));b.setAttribute('aria-label',liked?'Убрать из любимого':'В любимое');b.title=liked?'Убрать из любимого':'В любимое'}updateFocusTime()}toast(liked?'Добавлено в любимое':'Убрано из любимого')};
